/usr/bin/zsh -lc "cat > src/pricing.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Compare Acme Notes plans and choose the price that works for you.">
  <title>Pricing | Acme Notes</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #172334; background: #f6f8fb; }
    * { box-sizing: border-box; }
    body { margin: 0; }
    main { max-width: 1060px; margin: auto; padding: 80px 24px; }
    header { text-align: center; margin-bottom: 48px; }
    .brand { font-weight: 700; color: #455873; }
    h1 { font-size: clamp(2.5rem, 6vw, 4rem); letter-spacing: -.04em; margin: 16px 0; }
    header p { color: #455873; line-height: 1.6; }
    .tiers { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
    .tier { background: white; border: 1px solid #d9e1ed; border-radius: 20px; padding: 32px; }
    h2 { font-size: 1.35rem; margin: 0 0 28px; }
    .price { font-size: 3rem; font-weight: 700; letter-spacing: -.04em; margin: 0; }
    @media (max-width: 640px) { main { padding: 48px 20px; } .tiers { grid-template-columns: 1fr; } }
  </style>
</head>
<body>
  <main>
    <header>
      <p class="brand">Acme Notes</p>
      <h1>Pricing</h1>
      <p>Choose the plan that works for you.</p>
    </header>
    <section class="tiers" aria-label="Pricing plans">
      <!-- TODO: apply the owner'"'s tier-name choice from the comparison artifact. -->
      <article class=\"tier\"><h2>TIER_1</h2><p class=\"price\">"'$0</p></article>
      <article class="tier"><h2>TIER_2</h2><p class="price">$8</p></article>
      <article class="tier"><h2>TIER_3</h2><p class="price">$20</p></article>
    </section>
  </main>
</body>
</html>
EOF'
